window.REPORT_PRELOAD_CACHE["UNH.html"] = {"version":"b23a382e0684668904232b17b59407e77db97977ee72ab04b05729de4336b6e9","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>联合健康集团 UnitedHealth Group (NYSE: UNH) 深度商业与投资价值分析报告</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n unhblue: {\n 300: '#7DD3FC',\n 400: '#38BDF8',\n 500: '#0284C7',\n 600: '#0369A1',\n 700: '#075985',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar { width: 6px; height: 6px; }\n ::-webkit-scrollbar-track { background: transparent; }\n ::-webkit-scrollbar-thumb { background: #94A3B8; border-radius: 3px; }\n .dark ::-webkit-scrollbar-thumb { background: #475569; }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print { display: none !important; }\n main { margin-left: 0 !important; padding: 0 !important; }\n section { break-inside: avoid; }\n }\n\n .report-card { transition: transform 0.2s ease, box-shadow 0.2s ease; }\n .report-card:hover { transform: translateY(-2px); }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(3, 105, 161, 0.25) 0%, rgba(16, 185, 129, 0.05) 100%);\n border-left: 3px solid #0284C7;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-unhblue-500 selection:text-white transition-colors duration-200\">\n\n <!-- 全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-unhblue-600 via-unhblue-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-unhblue-600 to-navy-900 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n UNH\n </div>\n <div>\n <div class=\"text-[11px] text-unhblue-300 font-semibold tracking-wider uppercase\">NYSE: UNH · Managed Care & Health Services</div>\n <div class=\"text-sm font-bold leading-tight\">联合健康集团深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 text-slate-300\" aria-label=\"主题切换\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 text-white\" aria-label=\"菜单\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端抽屉 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">UNH 研报目录</span>\n <button onclick=\"toggleMobileMenu()\" class=\"text-slate-400 hover:text-white\">✕</button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">00. 执行摘要与最新财报</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">01. 商业模式：UnitedHealthcare 与 Optum 双引擎</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">02. 核心竞争优势与医疗生态壁垒</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">03. 财务表现与 Q3 2026 业绩洞察</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">04. 同业竞争与市场格局</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">05. 估值展望与投资策略</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800\">06. 跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>美股医疗健康龙头研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 财报)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧边栏 (280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-unhblue-600 to-navy-900 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-unhblue-600/25\">\n UNH\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-unhblue-300 bg-unhblue-500/15 px-2 py-0.5 rounded\">NYSE: UNH</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">联合健康集团研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 全球医疗健康与保险服务绝对龙头 · 覆盖上亿患者的 Managed Care 与 Optum 科技医疗双轮驱动\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">最新股价 (Q4 2026)</span>\n <span class=\"font-mono font-bold text-white\">~$412.24 <span class=\"text-slate-400 text-[10px]\">($255-$461)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">第三季度营业收入</span>\n <span class=\"font-mono font-bold text-emerald-400\">$1127亿 (运营利润$66亿)</span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">全年调整后 EPS 指引</span>\n <span class=\"font-mono font-bold text-unhblue-300\">至少 $20.50/股</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">报告核心章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-unhblue-400 mr-2\">00</span>执行摘要与最新财报</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>商业模式：保险与科技双引擎</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>核心优势与医疗生态壁垒</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>财务表现与 Q3 2026 业绩洞察</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>同业竞争与市场格局</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>估值展望与投资策略</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">页面显示模式</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-unhblue-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-unhblue-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色模式</span>\n <span class=\"hidden dark:inline\">浅色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-unhblue-600 to-unhblue-700 hover:from-unhblue-700 text-white text-xs font-extrabold transition cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span class=\"text-white\">打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. 封面与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-unhblue-500/15 text-unhblue-700 dark:text-unhblue-300 font-bold border border-unhblue-500/30\">机构评级：买入 (Outperform / Buy)</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">覆盖基准：2026年第三季度财报与行业展望</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>股票代码：NYSE: UNH</span>\n <span>总市值：~$3,690 亿</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#0284C7 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-unhblue-500/20 border border-unhblue-400/40 text-unhblue-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-unhblue-400 animate-pulse\"></span>\n <span>EXECUTIVE SUMMARY · Q3 营收 $1127亿 × 医疗费用率优化至 88.4% × 全年 EPS 指引上调至 $20.50+</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 联合健康集团 UnitedHealth Group Inc. (NYSE: UNH) 深度商业与投资价值分析报告\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 联合健康集团（UnitedHealth Group, 代码：<strong class=\"text-white\">UNH</strong>）作为全球医疗健康与保险服务的绝对龙头，在 <strong class=\"text-unhblue-300\">2026财年第三季度财报</strong>中交出了强劲的利润修复答卷 [cite: 1.3.2]。本季度实现营业收入 <strong class=\"text-white\">$1127亿美元</strong>，运营利润达 <strong class=\"text-emerald-400\">$66亿美元</strong>，调整后每股收益 EPS 达到 <strong class=\"text-unhblue-300\">$4.69</strong> [cite: 1.2.1]。\n 凭借 UnitedHealthcare 健康保险与 Optum 医疗科技/药房服务的双轮驱动，叠加出色的医疗成本控制（MCR 降至 88.4%），公司再次上调全年盈利指引，展现出穿越周期的顶尖护城河 [cite: 1.2.1, 1.3.3]。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">Q3 营收与利润双优</div>\n <div class=\"text-white font-semibold\">营业收入 $1127 亿，运营利润 $66 亿，调整后 EPS $4.69 超出市场预期 [cite: 1.2.1, 1.3.2]</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">医疗成本率 (MCR) 改善</div>\n <div class=\"text-unhblue-300 font-semibold\">MCR 优化至 88.4%（同比下降 1.5 个百分点），彰显精细化医疗成本管理成效 [cite: 1.2.2]</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">全年盈利指引持续上调</div>\n <div class=\"text-emerald-400 font-semibold\">全年调整后 EPS 预期上调至至少 $20.50/股，彰显高确定性成长 [cite: 1.2.1]</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 四大核心 KPI 指标卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 2026 营业收入</span>\n <span class=\"p-1.5 rounded-lg bg-unhblue-500/15 text-unhblue-600 dark:text-unhblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$1127亿</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">全球医疗巨无霸</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 第三季度总营收达 1127 亿美元，稳居全球医疗健康服务行业营收规模第一 [cite: 1.2.1, 1.2.3]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>第三季度运营利润</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$66亿</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">同比增长显著</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 运营利润达 66 亿美元，较去年同期的 43 亿美元大幅提升，展现出极强的利润修复能力 [cite: 1.2.1, 1.2.2]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>调整后每股收益 (EPS)</span>\n <span class=\"p-1.5 rounded-lg bg-unhblue-500/15 text-unhblue-600 dark:text-unhblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$4.69</span>\n <span class=\"text-xs font-bold text-unhblue-600 dark:text-unhblue-400 bg-unhblue-500/15 px-2 py-0.5 rounded\">超市场预期</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 第三季度调整后 EPS 达到 $4.69（超出分析师预期的 $4.12），盈利能力强劲反弹 [cite: 1.3.2, 1.3.3]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>医疗成本率 (MCR)</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">88.4%</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">同比优化 1.5%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 医疗护理成本率从去年同期的 89.9% 优化降至 88.4%，反映出出色的医疗成本管控与精准定价策略 [cite: 1.2.2]。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 商业模式与双引擎生态\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-unhblue-600 dark:text-unhblue-400\">Section 01 · Business Model & Dual Engines</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 商业模式：UnitedHealthcare 保险与 Optum 医疗科技双轮驱动</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">协同效应：支付方 (Payer) + 服务方 (Provider) 闭环生态</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">联合健康集团两大核心业务板块营收贡献 (%)</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\">UnitedHealthcare 健康保险与 Optum 医疗科技服务业务结构全景</p>\n </div>\n <span class=\"px-2.5 py-1 rounded bg-unhblue-500/15 text-unhblue-600 dark:text-unhblue-400 text-xs font-bold\">医保与医疗服务双巨头</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizSegmentChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业模式三大核心支柱</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-unhblue-500/15 text-unhblue-600 dark:text-unhblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">UnitedHealthcare 健康保险业务</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 服务超过 4800 万名消费者（涵盖雇主与个人、医疗保险退休人员 Medicare、以及 Medicaid 社区计划），提供全面的健康医疗保险保障 [cite: 1.2.2]。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Optum Health 医疗护理与价值医疗</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 为超过 1.2 亿患者提供直接医疗护理服务，通过门诊中心、医生网络和价值医疗（Value-Based Care）大幅提升治疗效率并降低整体医疗成本 [cite: 1.2.2]。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-unhblue-500/15 text-unhblue-600 dark:text-unhblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Optum Rx 药房福利管理 (PBM)</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 管理庞大的处方药福利，优化透明药品定价并推进生物类似药（Biosimilars）应用，三季度营收高达 399 亿美元，贡献稳健运营利润 [cite: 1.2.2]。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">生态系统优势</span>\n <span class=\"font-bold text-unhblue-600 dark:text-unhblue-400\">支付与服务的完美闭环，构筑超强协同</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 核心竞争优势与护城河\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Competitive Advantages & Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 核心竞争优势与医疗生态壁垒：支付与服务的飞轮效应</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 全球医疗绝对龙头)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-unhblue-500/15 text-unhblue-600 dark:text-unhblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">医保支付与医疗服务垂直一体化</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 通过旗下 UnitedHealthcare 保险汇聚海量会员，并由 Optum 提供直接诊疗与药房福利管理，形成独特闭环，有效消减中间环节摩擦成本。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">卓越的定价纪律与成本管控能力</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 面对医疗服务利用率波动，管理层迅速采取精准的定价调整与医疗成本管理，使三季度 MCR 顺利回落至 88.4%，展现出顶级运营韧性 [cite: 1.2.2]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-unhblue-500/15 text-unhblue-600 dark:text-unhblue-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">规模化患者网络与海量数据优势</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 医疗保险服务近 4800 万人、Optum 护理超 1.2 亿消费者，庞大的数据与诊疗经验赋能 AI 医疗洞察，不断优化医疗资源配置 [cite: 1.2.2]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">稳健的现金流与股东回报</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 三季度运营现金流高达 51 亿美元（达净利润的 1.2 倍），前三季度强力回购 69 亿美元股票并持续派发稳定股息 [cite: 1.2.1, 1.2.2]。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">全球医疗服务行业五维护城河雷达</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">UNH vs 同业竞争对手综合评分（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 财务表现与 Q3 2026 业绩洞察\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-unhblue-600 dark:text-unhblue-400\">Section 03 · Financial Performance & Q3 2026 Earnings</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 财务表现与 Q3 2026 业绩洞察：利润强劲修复与指引上调</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">运营利润达 $66亿 · 全年 EPS 预期上调至 $20.50+ [cite: 1.2.1]</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-unhblue-600 dark:text-unhblue-400 uppercase\">Q3 Operating Earnings</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$66.0亿</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 第三季度运营利润达到 66 亿美元，较去年同期的 43 亿美元大幅增长，显示出严谨的执行力与利润修复 [cite: 1.2.1, 1.2.2]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Operating Cash Flow</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$51.0亿</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 第三季度经营活动现金流达 51 亿美元（为净利润的 1.2 倍），资本实力极其雄厚 [cite: 1.2.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-unhblue-600 dark:text-unhblue-400 uppercase\">Share Repurchase</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$50.0亿</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 年初至今已回购 50 亿美元普通股（三季度单季回购积极），持续向市场传递对公司内在价值的强大信心 [cite: 1.2.2]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Debt-to-Capital Ratio</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">41.7%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 截至三季度末债务资本比率为 41.7%，公司目标在年底前稳步降至约 40.0% 的健康长期水平 [cite: 1.2.2]。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">联合健康集团近年营业收入与运营利润走势 ($ 亿美元)</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">万亿级医疗巨头稳步前行，盈利能力随成本精细化管理持续回升</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-unhblue-700 dark:text-unhblue-300 bg-unhblue-500/15 px-2.5 py-1 rounded\">稳健成长曲线</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"finTrendChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 同业竞争与市场格局\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-unhblue-600 dark:text-unhblue-400\">Section 04 · Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 同业竞争与市场格局：UNH 稳居全球医疗健康服务绝对龙头</h2>\n </div>\n <div class=\"flex items-center space-x-2 text-xs text-slate-500 dark:text-slate-400\">\n <span>对标同业：CVS Health, Elevance Health, Cigna</span>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">公司名称与代码</th>\n <th class=\"py-4 px-4 min-w-[130px]\">行业地位</th>\n <th class=\"py-4 px-4 min-w-[140px]\">季度营收规模</th>\n <th class=\"py-4 px-4 min-w-[120px]\">业务模式特点</th>\n <th class=\"py-4 px-5 min-w-[240px]\">核心竞争优势与业务亮点</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\">\n <tr class=\"bg-unhblue-500/5 dark:bg-unhblue-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-unhblue-700 text-white text-[10px] font-extrabold\">本文主角</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">UnitedHealth Group (NYSE: UNH)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球医疗绝对龙头</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全美第一大</td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~$1127 亿 (Q3) [cite: 1.2.1]</td>\n <td class=\"py-4 px-4 text-emerald-600 dark:text-emerald-400 font-semibold\">保险 + Optum 医疗闭环</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>双轮驱动护城河：</strong>兼具庞大健康保险网络与 Optum 医疗科技/药房服务，盈利能力与现金流稳居行业之首 [cite: 1.2.2, 1.2.3]。\n </td>\n </tr>\n\n <tr class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">CVS Health Corporation (NYSE: CVS)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">零售医疗与药房巨头</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全美领先综合医疗</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~$950 亿+</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">零售药房 + Aetna 保险</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>线下零售网络：</strong>拥有庞大 CVS Pharmacy 门店与 Aetna 保险，深度触达社区基层医疗。\n </td>\n </tr>\n\n <tr class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Elevance Health (NYSE: ELV)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">蓝十字蓝盾核心运营商</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全美领先健康险</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~$430 亿+</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">BCBS 授权网络</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>商保与政府医保：</strong>在多州拥有强大的蓝十字蓝盾（Blue Cross Blue Shield）品牌排他性运营授权。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 估值展望与投资策略\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-unhblue-600 dark:text-unhblue-400\">Section 05 · Valuation Outlook & Investment Strategy</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 估值展望与投资策略：华尔街目标价锚定 $460 – $506</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">机构共识平均目标价 ~$463.93（高盛/Piper Sandler看至 $504-$506） [cite: 1.1.2, 1.3.3]</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">乐观情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">目标价：$504 – $506</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">利润率超预期恢复</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>医疗成本率（MCR）持续下降，Optum 科技与药房板块增速加快，全年 EPS 超额突破指引上限。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 高盛 & Piper Sandler 目标价 $504-$506 [cite: 1.3.3]\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-unhblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-unhblue-500/15 text-unhblue-700 dark:text-unhblue-300 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-unhblue-600 dark:text-unhblue-400\">目标价：$460 – $465</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">全年指引顺利达成</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>公司稳步达成全年调整后 EPS 至少 $20.50 的指引，估值伴随盈利修复向历史均值回归 [cite: 1.2.1, 1.3.3]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-unhblue-600 dark:text-unhblue-400\">\n 华尔街 28 家投行平均目标价 ~$463.93 [cite: 1.1.2]\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">谨慎情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">目标价：$350 – $380</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">医疗利用率反弹或监管风险</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心逻辑：</strong>若未来数季医疗服务利用率意外大幅反弹，或政府医保（Medicare Advantage/Medicaid）政策趋严，将对利润构成扰动。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 需持续跟踪政策变化与老龄化就医趋势\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-unhblue-300 mb-3 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构投资策略建议</span>\n </h3>\n <p class=\"text-xs sm:text-sm text-slate-300 leading-relaxed\">\n 联合健康集团 (UNH) 作为美股医疗板块的定海神针，兼具强劲的现金创造能力与医疗科技成长属性。当前估值对应前瞻市盈率处于历史合理区间，三季度出色的利润修复与指引上调印证了其强大的基本面。建议投资者将其作为长线医疗资产配置的核心标的。\n </p>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 跟踪 KPI 核查清单\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Regular Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 定期跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-unhblue-500/15 text-unhblue-700 dark:text-unhblue-300 text-xs font-bold\">已核查 3 / 5 项 (60%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选 UNH 投资组合监控中的关键运营指标（本地状态自动保存）：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 医疗成本率（MCR）保持在健康稳定区间</span>\n <span class=\"text-[11px] font-mono text-unhblue-600 dark:text-unhblue-400 font-semibold shrink-0\">核心成本指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控 MCR 是否持续维持在优化水平（如 Q3 降至 88.4%），确保保险定价覆盖医疗通胀 [cite: 1.2.2]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. Optum 科技与药房板块稳健贡献运营利润</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">第二增长引擎</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪 Optum Health、Optum Insight 及 Optum Rx 的营收与利润贡献，验证多元化协同效应 [cite: 1.2.2]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 全年调整后 EPS 达成或超额完成管理层指引</span>\n <span class=\"text-[11px] font-mono text-unhblue-600 dark:text-unhblue-400 font-semibold shrink-0\">盈利达成度</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 核查全年调整后 EPS 是否顺利兑现至少 $20.50/股的业绩指引 [cite: 1.2.1]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 经营现金流保持对净利润 1.1x 倍以上的覆盖</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">现金流质量</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 确保强劲的现金流生成能力持续支持股票回购、股息派发与战略投资 [cite: 1.2.1]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 债务资本比率平稳向 40% 的长期目标收敛</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">资产负债健康</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 持续追踪杠杆率，确保资产负债表在宏观波动中保持顶级信用评级 [cite: 1.2.2]。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>联合健康集团 UnitedHealth Group Inc. (NYSE: UNH) 深度商业与投资价值分析报告 [cite: 1.2.1]</span>\n <span>数据基准：2026 年 Q3 财报与公开资本市场披露 [cite: 1.2.1]</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本报告基于 UnitedHealth Group 公开披露的财务财报、SEC 申报文件及市场分析数据撰写，旨在提供结构化商业研究参考。报告中的前瞻性预测、目标价及财务推演不构成任何直接证券投资建议。\n </p>\n </footer>\n\n </div>\n </main>\n\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-unhblue-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-unhblue-400');\n }\n }\n });\n });\n\n const KPI_STORAGE_KEY = 'unh_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizSegmentChartInstance = null;\n let moatRadarChartInstance = null;\n let finTrendChartInstance = null;\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizSegmentChart() {\n const ctx = document.getElementById('bizSegmentChart').getContext('2d');\n const colors = getChartColors();\n\n if (bizSegmentChartInstance) bizSegmentChartInstance.destroy();\n bizSegmentChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['UnitedHealthcare 保险业务', 'Optum Rx 药房福利管理', 'Optum Health 医疗护理服务', 'Optum Insight 医疗科技服务'],\n datasets: [\n {\n label: '各业务板块营收贡献占比估算 (%)',\n data: [55, 30, 10, 5],\n backgroundColor: '#0284C7',\n borderRadius: 6,\n barThickness: 24\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `营收占比约: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 70,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initMoatRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (moatRadarChartInstance) moatRadarChartInstance.destroy();\n moatRadarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '垂直一体化生态闭环 (保险+服务)',\n '庞大会员基数与渠道覆盖',\n '医疗成本管控与定价纪律',\n 'Optum 科技与药房创新能力',\n '自由现金流与资本回报实力'\n ],\n datasets: [\n {\n label: 'UNH (联合健康集团)',\n data: [9.8, 9.7, 9.5, 9.6, 9.8],\n borderColor: '#0284C7',\n backgroundColor: 'rgba(3, 105, 161, 0.22)',\n pointBackgroundColor: '#0284C7',\n borderWidth: 2.5\n },\n {\n label: '行业平均水平',\n data: [7.5, 8.2, 7.8, 8.0, 8.0],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.12)',\n pointBackgroundColor: '#10B981',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initFinTrendChart() {\n const ctx = document.getElementById('finTrendChart').getContext('2d');\n const colors = getChartColors();\n\n if (finTrendChartInstance) finTrendChartInstance.destroy();\n finTrendChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', '2026 (F)'],\n datasets: [\n {\n type: 'bar',\n label: '全年营业收入 Net Sales ($ 亿)',\n data: [3716, 4003, 4475, 4580],\n backgroundColor: 'rgba(3, 105, 161, 0.85)',\n borderRadius: 6,\n barThickness: 32,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '运营利润 Operating Earnings ($ 亿)',\n data: [324, 298, 255, 275],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 0,\n max: 5500,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + '亿' },\n title: { display: true, text: '营业收入 ($亿)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 400,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v + '亿' },\n title: { display: true, text: '运营利润 ($亿)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizSegmentChart();\n initMoatRadarChart();\n initFinTrendChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n initBizSegmentChart();\n initMoatRadarChart();\n initFinTrendChart();\n });\n </script>\n</body>\n</html>\n"};
